<?php require dirname(__DIR__).'/config/config.php'; require dirname(__DIR__).'/vendor/autoload.php'; use App\Helpers\Security; $u=Security::requireRole(['administrador','gerente']); $inicio=$_GET['inicio']??date('Y-m-01');$fim=$_GET['fim']??date('Y-m-d');$s=db()->prepare("SELECT COUNT(*) pedidos,COALESCE(SUM(valor),0) faturamento FROM pedidos WHERE DATE(data_pedido) BETWEEN ? AND ? AND status<>'cancelado'");$s->execute([$inicio,$fim]);$res=$s->fetch();$mais=db()->query("SELECT c.nome,COUNT(p.id) total FROM pedidos p JOIN clientes c ON c.id=p.cliente_id WHERE p.status<>'cancelado' GROUP BY p.cliente_id ORDER BY total DESC LIMIT 10")->fetchAll();$uso=db()->query("SELECT ca.tipo,COUNT(p.id) total FROM pedidos p JOIN cacambas ca ON ca.id=p.cacamba_id WHERE p.status<>'cancelado' GROUP BY ca.tipo ORDER BY total DESC")->fetchAll();?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Relatórios</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.4"></script></head><body><div class="container py-4"><h1>Relatórios</h1><a href="dashboard.php">← Dashboard</a><form class="row g-2 my-4"><div class="col-md-3"><input class="form-control" type="date" name="inicio" value="<?=Security::e($inicio)?>"></div><div class="col-md-3"><input class="form-control" type="date" name="fim" value="<?=Security::e($fim)?>"></div><div class="col-md-2"><button class="btn btn-primary">Filtrar</button></div></form><div class="row g-3"><div class="col-md-6"><div class="card p-3"><small>Pedidos no período</small><h2><?=$res['pedidos']?></h2></div></div><div class="col-md-6"><div class="card p-3"><small>Faturamento</small><h2>R$ <?=number_format((float)$res['faturamento'],2,',','.')?></h2></div></div></div><div class="row mt-4 g-4"><div class="col-md-6"><div class="card p-3"><h5>Clientes mais frequentes</h5><?php foreach($mais as $r):?><p><?=Security::e($r['nome'])?> <b>(<?=$r['total']?>)</b></p><?php endforeach;?></div></div><div class="col-md-6"><div class="card p-3"><h5>Caçambas mais utilizadas</h5><canvas id="chart"></canvas></div></div></div></div><script>new Chart(document.getElementById('chart'),{type:'bar',data:{labels:[<?php foreach($uso as $r)echo json_encode($r['tipo']).',';?>],datasets:[{label:'Pedidos',data:[<?php foreach($uso as $r)echo (int)$r['total'].',';?>]}]}});</script></body></html>
